// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract PolicyContract {

    address public insurer;

    // ================================
    // POLICY STRUCT
    // ================================
    struct Policy {
        uint policyId;
        string policyName;
        uint coverageLimit;
        uint premiumAmount;
        uint validityPeriod;
        string ipfsCID;
        string covered;
        string excluded;
        string status;
        uint timestamp;
    }

    // ================================
    // POLICY INPUT STRUCT
    // (fixes stack too deep error)
    // ================================
    struct PolicyInput {
        string policyName;
        uint coverageLimit;
        uint premiumAmount;
        uint validityPeriod;
        string ipfsCID;
        string covered;
        string excluded;
    }

    // ================================
    // SUBSCRIPTION STRUCT
    // ================================
    struct Subscription {
        uint policyId;
        string policyName;
        address patientAddress;
        uint premiumPaid;
        uint startDate;
        uint endDate;
        string subscriptionStatus;
        string paymentStatus;
        uint timestamp;
    }

    // ================================
    // STORAGE
    // ================================
    uint public policyCount = 0;
    uint public fundPool = 0;

    mapping(uint => Policy) public policies;
    mapping(address => Subscription) public subscriptions;
    mapping(address => bool) public hasActivePolicy;

    uint[] public allPolicyIds;

    // ================================
    // EVENTS
    // ================================
    event PolicyCreated(
        uint policyId,
        string policyName,
        uint coverageLimit,
        uint premiumAmount,
        uint timestamp
    );

    event PolicySubscribed(
        address patientAddress,
        uint policyId,
        string policyName,
        uint startDate,
        uint endDate,
        uint timestamp
    );

    event PremiumPaid(
        address patientAddress,
        uint policyId,
        uint amount,
        uint timestamp
    );

    // ================================
    // MODIFIER
    // ================================
    modifier onlyInsurer() {
        require(
            msg.sender == insurer,
            "Only insurer can do this"
        );
        _;
    }

    // ================================
    // CONSTRUCTOR
    // ================================
    constructor() {
        insurer = msg.sender;
    }

    // ================================
    // CREATE POLICY
    // uses struct to avoid
    // stack too deep error
    // ================================
    function createPolicy(
        PolicyInput memory input
    ) public onlyInsurer {

        require(
            bytes(input.policyName).length > 0,
            "Policy name required"
        );

        require(
            input.coverageLimit > 0,
            "Coverage limit must be greater than 0"
        );

        require(
            input.premiumAmount > 0,
            "Premium amount must be greater than 0"
        );

        policyCount++;

        policies[policyCount] = Policy(
            policyCount,
            input.policyName,
            input.coverageLimit,
            input.premiumAmount,
            input.validityPeriod,
            input.ipfsCID,
            input.covered,
            input.excluded,
            "Active",
            block.timestamp
        );

        allPolicyIds.push(policyCount);

        emit PolicyCreated(
            policyCount,
            input.policyName,
            input.coverageLimit,
            input.premiumAmount,
            block.timestamp
        );
    }

    // ================================
    // SUBSCRIBE TO POLICY
    // patient calls this
    // pays premium in ETH
    // ================================
    function subscribePolicy(
        uint _policyId
    ) public payable {

        require(
            !hasActivePolicy[msg.sender],
            "Already have active policy"
        );

        require(
            _policyId > 0 &&
            _policyId <= policyCount,
            "Policy does not exist"
        );

        Policy memory policy = policies[_policyId];

        require(
            keccak256(bytes(policy.status)) ==
            keccak256(bytes("Active")),
            "Policy is not active"
        );

        require(
            msg.value == policy.premiumAmount,
            "Incorrect premium amount"
        );

        fundPool += msg.value;

        uint startDate = block.timestamp;
        uint endDate = block.timestamp +
            (policy.validityPeriod * 365 days);

        subscriptions[msg.sender] = Subscription(
            _policyId,
            policy.policyName,
            msg.sender,
            msg.value,
            startDate,
            endDate,
            "Active",
            "Paid",
            block.timestamp
        );

        hasActivePolicy[msg.sender] = true;

        emit PolicySubscribed(
            msg.sender,
            _policyId,
            policy.policyName,
            startDate,
            endDate,
            block.timestamp
        );

        emit PremiumPaid(
            msg.sender,
            _policyId,
            msg.value,
            block.timestamp
        );
    }

    // ================================
    // GET POLICY DETAILS
    // ================================
    function getPolicy(
        uint _policyId
    ) public view returns (Policy memory) {

        require(
            _policyId > 0 &&
            _policyId <= policyCount,
            "Policy does not exist"
        );

        return policies[_policyId];
    }

    // ================================
    // GET ALL POLICY IDs
    // ================================
    function getAllPolicies()
        public
        view
        returns (uint[] memory)
    {
        return allPolicyIds;
    }

    // ================================
    // GET SUBSCRIPTION
    // ================================
    function getSubscription(
        address _patientAddress
    ) public view returns (Subscription memory) {

        require(
            hasActivePolicy[_patientAddress],
            "No active policy found"
        );

        return subscriptions[_patientAddress];
    }

    // ================================
    // CHECK IF PATIENT HAS POLICY
    // ================================
    function checkActivePolicy(
        address _patientAddress
    ) public view returns (bool) {
        return hasActivePolicy[_patientAddress];
    }

    // ================================
    // GET FUND POOL BALANCE
    // ================================
    function getFundPool()
        public
        view
        returns (uint)
    {
        return fundPool;
    }

    // ================================
    // DEACTIVATE POLICY
    // only insurer can do this
    // ================================
    function deactivatePolicy(
        uint _policyId
    ) public onlyInsurer {

        require(
            _policyId > 0 &&
            _policyId <= policyCount,
            "Policy does not exist"
        );

        policies[_policyId].status = "Inactive";
    }
}
